settings.custom_liquid:
{%- comment -%}
Breadcrumb mit "Primärer Collection".
Überspringen NUR dieser Kollektionen:
- UpOrder - Recommended Products (Handle: uporder-recommended-products)
- OrderlyEmails - Recommended Products (Handle: orderlyemails-recommended-products)
- not discounted (Handle: not-discounted)
Priorität der Kandidaten:
1) context collection (URL-Kontext)
2) product.metafields.custom.primary_collection (Referenz)
3) alle product.collections (in Reihenfolge)
Wir wählen die ERSTE erlaubte.
{%- endcomment -%}

{%- assign context_col = collection -%}
{%- assign primary_col = nil -%}
{%- if product.metafields and product.metafields.custom and product.metafields.custom.primary_collection and product.metafields.custom.primary_collection.value -%}
  {%- assign primary_col = product.metafields.custom.primary_collection.value -%}
{%- endif -%}

{%- comment -%} Kandidatenliste als |handle|-String aufbauen, um Duplikate sicher zu vermeiden {%- endcomment -%}
{%- assign candidates = '' -%}
{%- if context_col -%}
  {%- assign token = '|' | append: context_col.handle | append: '|' -%}
  {%- assign candidates = candidates | append: token -%}
{%- endif -%}
{%- if primary_col -%}
  {%- assign token = '|' | append: primary_col.handle | append: '|' -%}
  {%- unless candidates contains token -%}
    {%- assign candidates = candidates | append: token -%}
  {%- endunless -%}
{%- endif -%}
{%- if product and product.collections and product.collections.size > 0 -%}
  {%- for c in product.collections -%}
    {%- assign token = '|' | append: c.handle | append: '|' -%}
    {%- unless candidates contains token -%}
      {%- assign candidates = candidates | append: token -%}
    {%- endunless -%}
  {%- endfor -%}
{%- endif -%}

{%- assign candidate_handles = candidates | split: '|' -%}
{%- assign chosen_col = nil -%}

{%- comment -%} Schleife: erste erlaubte Kollektion wählen {%- endcomment -%}
{%- for h in candidate_handles -%}
  {%- if h != blank -%}
    {%- assign c = collections[h] -%}
    {%- if c -%}
      {%- assign handle = c.handle | downcase -%}
      {%- assign title  = c.title  | strip | downcase -%}
      {%- assign is_disallowed = false -%}
      {%- if handle == 'not-discounted'
            or handle == 'uporder-recommended-products'
            or handle == 'orderlyemails-recommended-products'
            or title  == 'not discounted'
            or title  == 'uporder - recommended products'
            or title  == 'orderlyemails - recommended products' -%}
        {%- assign is_disallowed = true -%}
      {%- endif -%}
      {%- unless is_disallowed -%}
        {%- assign chosen_col = c -%}
        {%- break -%}
      {%- endunless -%}
    {%- endif -%}
  {%- endif -%}
{%- endfor -%}

<nav class="breadcrumb" role="navigation" aria-label="breadcrumbs">
  <a href="{{ routes.root_url }}">Startseite</a>

  {%- if template contains 'product' -%}
    {%- if chosen_col -%}
      <span aria-hidden="true">›</span>
      <a href="{{ chosen_col.url }}">{{ chosen_col.title }}</a>
    {%- endif -%}
    <span aria-hidden="true">›</span>
    <span>{{ product.title }}</span>

  {%- elsif template contains 'collection' and collection -%}
    <span aria-hidden="true">›</span>
    <span>{{ collection.title }}</span>

  {%- elsif template contains 'page' -%}
    <span aria-hidden="true">›</span>
    <span>{{ page.title }}</span>

  {%- elsif template contains 'blog' -%}
    <span aria-hidden="true">›</span>
    <span>{{ blog.title }}</span>

  {%- elsif template contains 'article' -%}
    <span aria-hidden="true">›</span>
    <a href="{{ blog.url }}">{{ blog.title }}</a>
    <span aria-hidden="true">›</span>
    <span>{{ article.title }}</span>
  {%- endif -%}
</nav>

