<div class="product-price" id="price-prod-{{ product.id }}">
  <span class="regular-price" data-price-cents="{{ current_variant.price }}">
    {{ current_variant.price | money }}
  </span>
  <span class="price-vat-note">inkl. MwSt.</span>
</div>

<style>
  .product-price {
    display: flex;
    align-items: baseline;
    gap: 6px;
    margin: 0 !important;
    padding: 0 !important;
  }
  .product-price .regular-price {
    font-size: 2em;
    font-weight: 600;
    line-height: 1;
    margin: 0 !important;
    padding: 0 !important;
  }
  .product-price .price-vat-note {
    font-size: 0.75rem;
    color: #666;
    margin: 0 !important;
    padding: 0 !important;
  }
</style>

<script>
(function() {
  var root = document.getElementById('price-prod-{{ product.id }}');
  if (!root) return;

  var priceEl = root.querySelector('.regular-price');

  // ------------- Formatting -------------
  function formatMoney(cents) {
    // Bevorzugt die Shopify-Helferfunktion (verhindert Platzhalter im DOM)
    if (window.Shopify && typeof Shopify.formatMoney === 'function') {
      return Shopify.formatMoney(cents, {{ shop.money_format | json }});
    }
    // Fallback: simple, lokale Formatierung ohne Platzhalter
    try {
      return (Number(cents)/100).toLocaleString(undefined, {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      });
    } catch(e) {
      return (Number(cents)/100).toFixed(2);
    }
  }

  function render(cents) {
    if (cents == null) return;
    priceEl.textContent = formatMoney(cents);
  }

  // ------------- Varianten-Daten -------------
  var variants = {{ product.variants | json }};
  function getVariantById(id) {
    id = Number(id);
    for (var i = 0; i < variants.length; i++) {
      if (variants[i].id === id) return variants[i];
    }
    return null;
  }

  // ------------- Event-Hooks (verschiedene Theme-Varianten) -------------
  function onVariantEvent(e) {
    var v = e.detail && (e.detail.variant || e.detail);
    if (v && typeof v.price === 'number') render(v.price);
  }

  // Häufig genutzte Custom Events in OS 2.0 Themes:
  document.addEventListener('variant:change', onVariantEvent);
  document.addEventListener('product:variant-change', onVariantEvent);
  document.addEventListener('variant:changed', onVariantEvent);

  // Fallback: auf Änderungen an [name="id"] (Select/Radio) hören
  document.addEventListener('change', function(e) {
    var t = e.target;
    if (!t) return;
    if (t.name === 'id') {
      var id = t.value || (t.form ? new FormData(t.form).get('id') : null);
      var v = id && getVariantById(id);
      if (v) render(v.price);
    }
  });

  // ------------- Initiale Korrektur (falls Server-Preis nicht passt) -------------
  var selectedInput = document.querySelector('form[action*="/cart/add"] [name="id"]:checked, form[action*="/cart/add"] select[name="id"]');
  if (selectedInput && selectedInput.value) {
    var v = getVariantById(selectedInput.value);
    if (v) render(v.price);
  }
})();
</script>

